INSERT INTO chips (id, situation_id, code, label, text_formal, text_brief, text, default_on, sort_order) VALUES (1, 1, 'alt', '대안 일정 요청', '제안드린 일정이 어려우시면 편하신 일정을 알려주시면 최대한 맞추겠습니다.', '어려우시면 가능한 일정 알려주세요.', NULL, 1, 0), (2, 1, 'online', '화상회의 가능', '대면 미팅이 어려우시면 화상회의로 진행하는 것도 가능합니다.', '화상회의도 가능합니다.', NULL, 0, 1), (3, 1, 'dur', '소요 시간 안내', '미팅은 1시간 내외로 진행될 예정입니다.', '1시간 정도 예상합니다.', NULL, 0, 2), (4, 1, 'agenda', '안건 사전 공유', '논의 안건은 일정 확정 후 미리 공유드리겠습니다.', '안건은 확정 후 공유드릴게요.', NULL, 0, 3), (5, 2, 'purpose', '사용 목적 설명', '요청드린 자료는 내부 검토 및 의사결정 목적으로만 활용하겠습니다.', '내부 검토용으로만 사용합니다.', NULL, 1, 0), (6, 2, 'format', '파일 형식 지정', '가능하시다면 PDF 또는 엑셀 파일로 전달해 주시면 감사하겠습니다.', 'PDF나 엑셀로 주시면 좋겠습니다.', NULL, 0, 1), (7, 2, 'contact', '담당자 안내 요청', '자료 관련해 문의드릴 수 있는 담당자분도 함께 알려주시면 감사하겠습니다.', '담당자 연락처도 함께 부탁드립니다.', NULL, 0, 2), (8, 2, 'nda', '보안 유지 약속', '전달해 주신 자료는 외부로 유출되지 않도록 철저히 관리하겠습니다.', '자료는 보안 유지하겠습니다.', NULL, 0, 3), (9, 3, 'cause', '원인 간략 설명 포함', '지연 사유는 다음과 같습니다.
{memo}', '사유
{memo}', NULL, 1, 0), (10, 3, 'emph', '변경된 일정 강조', '▶ 변경 완료 예정일: {newDate}
위 일정은 반드시 지킬 수 있도록 최선을 다하겠습니다.', '▶ 변경 예정일: {newDate}
이 일정은 꼭 지키겠습니다.', NULL, 1, 1), (11, 3, 'prevent', '재발 방지 약속', '앞으로 같은 일이 반복되지 않도록 일정 관리 체계를 점검하고 보완하겠습니다.', '재발하지 않도록 일정 관리 철저히 하겠습니다.', NULL, 0, 2), (12, 3, 'share', '진행 상황 공유', '진행 상황은 중간중간 공유드려 걱정을 덜어 드리겠습니다.', '진행 상황은 수시로 공유드리겠습니다.', NULL, 0, 3), (13, 4, 'agenda', '안건 포함', '논의 안건은 다음과 같습니다.
{memo}', '안건
{memo}', NULL, 1, 0), (14, 4, 'prep', '사전 자료 검토 요청', '원활한 논의를 위해 관련 자료를 미리 검토해 주시면 감사하겠습니다.', '관련 자료 미리 확인 부탁드립니다.', NULL, 0, 1), (15, 4, 'rsvp', '참석 여부 회신 요청', '참석 가능 여부를 회신해 주시면 준비에 참고하겠습니다.', '참석 여부 회신 부탁드립니다.', NULL, 0, 2), (16, 4, 'change', '변동 시 연락 요청', '일정에 변동이 있으시면 미리 말씀해 주십시오.', '변동 있으면 미리 알려주세요.', NULL, 1, 3), (17, 5, 'bg', '배경 설명 포함', '이번 요청은 {proj} 일정을 안정적으로 맞추기 위해 꼭 필요한 사항입니다.', '{proj} 일정 맞추려면 꼭 필요한 부분입니다.', NULL, 1, 0), (18, 5, 'benefit', '기대 효과 언급', '협조해 주시면 양측 모두 업무 효율을 높일 수 있을 것으로 기대합니다.', '협조해 주시면 일정 단축에 큰 도움이 됩니다.', NULL, 0, 1), (19, 5, 'meet', '짧은 미팅 제안', '필요하시면 짧게 미팅을 잡아 자세히 설명드리겠습니다.', '필요하면 짧게 미팅하시죠.', NULL, 0, 2), (20, 5, 'person', '담당자 연결 요청', '해당 업무 담당자분을 알려주시면 직접 연락드리겠습니다.', '담당자 알려주시면 직접 연락드릴게요.', NULL, 0, 3), (21, 6, 'coop', '협조 요청 강조', NULL, NULL, '※ 원활한 진행을 위해 각 부서의 적극적인 협조 부탁드립니다.', 1, 0), (22, 6, 'change', '변경 사항 강조', NULL, NULL, '※ 기존 안내와 달라진 부분이 있으니 반드시 확인 바랍니다.', 0, 1), (23, 6, 'share', '팀 내 공유 요청', NULL, NULL, '※ 각 팀장님께서는 팀원들에게 내용 공유 부탁드립니다.', 0, 2), (24, 6, 'must', '필수 이행 안내', NULL, NULL, '※ 대상자는 기한 내 반드시 완료해 주시기 바랍니다.', 0, 3), (25, 7, 'first', '선착순 마감', NULL, NULL, '※ 정원이 한정되어 있어 선착순으로 마감될 수 있습니다.', 1, 0), (26, 7, 'approve', '팀장 승인 필요', NULL, NULL, '※ 신청 전 소속 팀장님의 승인을 받아 주시기 바랍니다.', 0, 1), (27, 7, 'cancel', '불참 시 취소 안내', NULL, NULL, '※ 불참 시 신청 마감일 전까지 취소해 주시기 바랍니다.', 0, 2), (28, 7, 'online', '온라인 참여 가능', NULL, NULL, '※ 현장 참석이 어려운 분은 온라인으로도 참여하실 수 있습니다.', 0, 3), (29, 8, 'stop', '서비스 중단 강조', NULL, NULL, '※ 점검 시간 동안 서비스 접속이 일시 중단됩니다.', 1, 0), (30, 8, 'save', '사전 저장 권고', NULL, NULL, '※ 작업 중인 문서는 점검 시작 전 반드시 저장해 주시기 바랍니다.', 1, 1), (31, 8, 'early', '조기 종료 가능', NULL, NULL, '※ 작업 상황에 따라 점검이 조기 종료될 수 있습니다.', 0, 2), (32, 8, 'extend', '연장 가능성 안내', NULL, NULL, '※ 점검 상황에 따라 종료 시간이 다소 연장될 수 있습니다.', 0, 3), (33, 9, 'resume', '업무 재개일 강조', NULL, NULL, '※ {resume}부터 정상 업무가 재개됩니다.', 1, 0), (34, 9, 'emergency', '긴급 연락처 안내', NULL, NULL, '※ 휴무 기간 중 긴급 사항은 문의처로 연락 바랍니다.', 0, 1), (35, 9, 'queue', '접수 건 처리 안내', NULL, NULL, '※ 휴무 기간 중 접수된 건은 업무 재개 후 순차적으로 처리됩니다.', 0, 2), (36, 9, 'handover', '업무 인수인계 요청', NULL, NULL, '※ 휴무 전 진행 중인 업무는 담당자 간 인수인계 부탁드립니다.', 0, 3);

